package com.cpf.batch.scheduler; import com.cpf.batch.runtime.RuntimeStateProvider; import com.cpf.batch.scheduler.internal.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.Duration; import java.util.concurrent.atomic.AtomicReference;
@Component public class SchedulerCoordinator implements RuntimeStateProvider { private final JdbcSchedulerLeaderRepository repo;private final String id;private final Duration duration;private final AtomicReference<JdbcSchedulerLeaderRepository.Lease> lease=new AtomicReference<>(); public SchedulerCoordinator(JdbcSchedulerLeaderRepository r,@Value("${cpf.batch.runtime.instance-id:${CPF_INSTANCE_ID:scheduler-local-01}}")String i,@Value("${cpf.batch.scheduler.lease-seconds:15}")long s){repo=r;id=i;duration=Duration.ofSeconds(Math.max(5,s));} @Scheduled(fixedDelayString="${cpf.batch.scheduler.election-ms:3000}") public void elect(){var l=lease.get();if(l!=null&&repo.heartbeat("BAT_SCHEDULER",l,duration))return;lease.set(repo.acquire("BAT_SCHEDULER",id,duration).orElse(null));} public void assertLeader(long token){var l=lease.get();if(l==null||l.fencingToken()!=token)throw new IllegalStateException("Stale scheduler leader fenced");} public long fencingToken(){return lease.get()==null?0:lease.get().fencingToken();} }
